// Normalize and tag Grooming Transcript
let combinedText = '';

for (const item of items) {
  // after extraction, text is inside item.json.data
  const text = item.json?.data?.toString().trim();
  if (text) combinedText += '\n' + text;
}

// cleanup formatting
combinedText = combinedText
  .replace(/\r/g, '')
  .replace(/\n{3,}/g, '\n\n')
  .replace(/[ \t]{2,}/g, ' ')
  .trim();

return [
  {
    json: {
      sourceName: "Grooming Transcript",
      sourceType: "TRANSCRIPT",
      text: `### Source: GROOMING TRANSCRIPT\n${combinedText}`,
      timestamp: new Date().toISOString()
    }
  }
];

// Merge all normalized document + transcript text into one large context
let allTexts = [];

for (const item of items) {
  const src = item.json.sourceType || item.json.sourceName || "Unknown Source";
  const txt = item.json.text || "";

  if (txt.trim()) {
    allTexts.push(txt); // already has Source: tags
  }
}

// Optional: Insert separator between sources
const merged = allTexts.join("\n\n---\n\n");

return [{
  json: {
    mergedContext: merged,
    contextCount: allTexts.length
  }
}];

// Get text safely from previous node (supports both JSON and binary markdown)
let md = "";

// Case 1: Markdown came as text field in JSON
if (items[0]?.json?.output?.[0]?.content?.[0]?.text) {
  md = items[0].json.output[0].content[0].text;
}

// Case 2: Markdown came as binary file
else if (items[0]?.binary?.data) {
  md = Buffer.from(items[0].binary.data.data, 'base64').toString('utf8');
}

// Case 3: Markdown as plain text field
else if (items[0]?.json?.data) {
  md = items[0].json.data;
}

else {
  return [{ json: { error: "No markdown input found for cleaning" } }];
}

// Clean and format Markdown
let cleaned = md
  .replace(/#+\s+/g, match => `\n\n${match}`) // add spacing before headings
  .replace(/-{3,}/g, '\n\n\\page\n\n')         // convert --- to page breaks
  .replace(/\n{3,}/g, '\n\n')                  // collapse extra newlines
  .trim();

return [{
  json: {
    cleanedMarkdown: cleaned
  }
}];

return items.map(item => {
  if (item.binary && item.binary.data) {
    item.binary.transcript = item.binary.data4; // copy to brd
    // do NOT delete data
  }
  return item;
});

return items.map(item => {
  if (item.binary && item.binary.data) {
    item.binary.lld = item.binary.data3; // copy to brd
    // do NOT delete data
  }
  return item;
});

return items.map(item => {
  if (item.binary && item.binary.data) {
    item.binary.hld = item.binary.data2; // copy to brd
    // do NOT delete data
  }
  return item;
});

return items.map(item => {
  if (item.binary && item.binary.data) {
    item.binary.frd = item.binary.data1; // copy to brd
    // do NOT delete data
  }
  return item;
});

return items.map(item => {
  if (item.binary && item.binary.data) {
    item.binary.brd = item.binary.data0; // copy to brd
    // do NOT delete data
  }
  return item;
});

// Normalize and tag each document extract with type headers
const cleanedDocs = [];

for (const item of items) {
  const d = item.json || {};
  const text = d.text || "";

  // Identify document type
  const type =
    d.fileName?.match(/BRD|FRD|HLD|LLD/i)?.[0]?.toUpperCase() || "DOCUMENT";

  // Basic cleaning: remove extra spaces, page numbers, headers/footers
  const cleaned = text
    .replace(/\bPage\s+\d+\b/gi, "") // remove page numbers
    .replace(/\n\s*\n\s*\n+/g, "\n\n") // collapse multiple newlines
    .replace(/[ \t]{2,}/g, " ") // remove excessive spaces
    .trim();

  cleanedDocs.push({
    json: {
      sourceName: d.fileName || "Unknown Document",
      sourceType: type,
      text: `### Source: ${type}\n${cleaned}`,
      timestamp: new Date().toISOString(),
    },
  });
}

return cleanedDocs;
